node -e "const { TokenBucket } = require('./kova.js');
// Basic test
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5, now: () => 0 });
console.log('Initial tokens:', bucket.available());
console.log('tryTake(3):', bucket.tryTake(3));
console.log('After take:', bucket.available());
console.log('msUntil(5):', bucket.msUntil(5));

// Time advance test
let time = 0;
const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 5, now: () => time });
bucket2.tryTake(10);
time = 1000;
console.log('After 1s, available:', bucket2.available());
console.log('msUntil(10):', bucket2.msUntil(10));
time = 2000;
console.log('After 2s, available:', bucket2.available());

// Edge cases
console.log('msUntil > capacity:', bucket2.msUntil(15));
console.log('Zero refill:', new TokenBucket({ capacity: 10, refillPerSecond: 0, now: () => 0 }).msUntil(5));

// Error cases
try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); } catch(e) { console.log('capacity 0 error:', e.message); }
try { new TokenBucket({ capacity: 10, refillPerSecond: -1 }); } catch(e) { console.log('negative refill error:', e.message); }
try { bucket.tryTake(0); } catch(e) { console.log('tryTake 0 error:', e.message); }
try { bucket.msUntil(-1); } catch(e) { console.log('msUntil negative error:', e.message); }
"
